mapper.select:
select episode_id, anchor_type, evaluated_at, outcome, algorithm_version, payload::text as payload
  from market_indicator_episode_outcomes
 where deleted_at is null
   and evaluated_at::date = #{tradeDate}
 order by evaluated_at desc
 limit #{limit}

select e.id, e.trade_date, e.code, e.name, e.market, e.event_type, e.event_at,
       e.signal_value, e.last_price, e.change_pct, e.limit_status, e.source
  from market_indicator_events e
 where e.deleted_at is null
   and e.trade_date = #{tradeDate}
   and e.event_at >= #{from}
   and e.event_at <= #{to}
   and e.event_type = #{eventType}

       and exists (
           select 1
             from ths_industry_constituent_snapshot constituent
            where constituent.deleted_at is null
              and constituent.industry_code = #{industryCode}
              and constituent.stock_code = right(e.code, 6)
              and constituent.snapshot_date = (
                  select max(snapshot.snapshot_date)
                    from ths_industry_constituent_snapshot snapshot
                   where snapshot.deleted_at is null
                     and snapshot.industry_code = #{industryCode}
                     and snapshot.snapshot_date <= #{tradeDate}
              )
       )

 order by e.event_at asc, e.id asc
 limit #{limit}

select i.id, i.trade_date, i.captured_at, i.industry_code, i.industry_name, i.stock_count,
       i.advancing_count, i.declining_count, i.flat_count, i.limit_up_count,
       i.limit_up_touch_count, i.limit_down_count, i.limit_down_touch_count,
       i.rapid_rise_count, i.rapid_fall_count, i.first_limit_up_at, i.first_limit_up_code,
       i.first_limit_up_name, i.first_limit_up_change_pct, i.first_event_at,
       i.first_event_code, i.first_event_name, i.first_event_type,
       i.first_event_signal_value, i.source
  from market_indicator_industry_snapshots i
 where i.deleted_at is null
   and i.trade_date = #{tradeDate}
   and i.captured_at >= #{from}
   and i.captured_at <= #{to}
   and i.industry_code = #{industryCode}
 order by i.captured_at asc, i.industry_name asc
 limit #{limit}

choose.when:
select pool_type, membership, industry_code, stocks::text as stocks
  from trade_review_minute_pool_index
 where trade_date = #{tradeDate} and minute_at = (
    select max(minute_at) from trade_review_minute_pool_index where trade_date = #{tradeDate} and minute_at <= #{asOf}
 ) and membership = #{membership}

       and industry_code = #{industryCode}
       and coalesce(industry_code, '') = ''

 order by pool_type

choose.otherwise:
select pool_type, membership, industry_code, stocks::text as stocks
 from trade_review_daily_pool
 where trade_date = #{tradeDate} and membership = #{membership}

       and industry_code = #{industryCode}
       and coalesce(industry_code, '') = ''

 order by pool_type

mapper.select:
select trade_date, advancing_count, declining_count, flat_count, above_5_count, below_minus_5_count,
       touched_limit_up_count, sealed_limit_up_count, broken_limit_up_count, sealed_limit_down_count,
       max_height, seal_rate, break_rate, promotion_rate, break_streak_rate, ladder::text as ladder
  from trade_review_market_daily_state
 where trade_date <= #{tradeDate}
 order by trade_date desc limit #{windowDays}

select trade_date, scope, membership, industry_code, window_days, phase, phase_score,
       factor::text as factor, policy_version
  from trade_review_trend_phase
 where trade_date = #{tradeDate} and scope = 'industry' and membership = #{membership}
   and window_days = #{windowDays}
   and industry_code = #{industryCode}
 order by phase_score desc, industry_code
